/**
 * Simplified domain model for the course sync job.
 *
 * The real system stores one document per (courseId, subject, number):
 * a course can be renumbered over time (e.g. COLWRIT 6A -> COLWRIT 22B),
 * and the store keeps rows for numbers that are no longer "current" because
 * past-term classes still join against them by courseId.
 */

/** A row as it currently sits in the local store, keyed by (courseId, subject, number). */
export interface StoredCourseRow {
  courseId: string;
  subject: string;
  number: string;
  title: string;
}

/** A row as returned by the upstream system's "current" course fetch. */
export interface FetchedCourse {
  courseId: string;
  subject: string;
  number: string;
  title: string;
}

/** A class record from a separate collection that joins to courses by courseId only. */
export interface ClassRecord {
  classId: string;
  courseId: string;
  term: string;
}

/**
 * The result of pulling every page of courses from upstream.
 *
 * `failedPages` lists the (simulated) page numbers that could not be fetched
 * even after retries. A non-empty `failedPages` means `courses` is NOT the
 * full current snapshot -- some rows that exist upstream may be missing here
 * for no reason other than a transient page failure.
 */
export interface FetchResult {
  courses: FetchedCourse[];
  failedPages: number[];
}

export interface ReconcileInput {
  /** The store's current rows before this sync run. */
  stored: StoredCourseRow[];
  /** Fetches the full current snapshot from upstream (paginated internally). */
  fetchCourses: () => Promise<FetchResult>;
}

export interface ReconcileResult {
  /** The store's rows after this sync run. */
  stored: StoredCourseRow[];
  upsertedCount: number;
  deletedCount: number;
}
